<?php require __DIR__.'/app/bootstrap.php';$u=require_user();require_commerce();$batch=one('SELECT * FROM order_batches WHERE id=? AND customer_id=?',[param('batch'),$u['id']]);if(!$batch)fail(404,'Order confirmation not found.');$orders=all('SELECT * FROM orders WHERE batch_id=? AND customer_id=? ORDER BY id',[$batch['id'],$u['id']]);$title='Order placed';require ROOT.'/app/header.php'; ?>
<main class="page shell medium" id="main"><div class="page-heading"><span class="heading-kicker">THANK YOU FOR ORDERING</span><h1>Your order is placed.</h1><p>Follow each shop’s progress from My Orders.</p></div><div class="saved-grid"><?php foreach($orders as $order): $items=all('SELECT * FROM order_items WHERE order_id=? ORDER BY id',[$order['id']]); ?><section class="panel padded"><?php render_order_summary($order,$items); ?><a class="pill primary" href="<?=e(url('order.php?id='.$order['id']))?>">View Order →</a></section><?php endforeach ?></div><p><a class="pill" href="<?=e(url('orders.php'))?>">My Orders</a> <a class="pill" href="<?=e(url('index.php'))?>">Explore Food</a></p></main><?php require ROOT.'/app/footer.php'; ?>
